const { withPodfile } = require("expo/config-plugins");

const marker = "# SimplySync: keep every generated Pod target on the app minimum.";

/**
 * CocoaPods can retain a podspec's old deployment target on resource bundles
 * even when the app and library targets use ios.deploymentTarget. New Xcode
 * SDKs reject those bundle targets, so apply the same minimum to every target
 * generated by `pod install`.
 */
module.exports = function withSupportedPodTargets(config) {
  return withPodfile(config, (mod) => {
    if (mod.modResults.contents.includes(marker)) return mod;

    const postInstallEnd = /(\s+react_native_post_install\([\s\S]*?\n\s+\)\n)(\s+end\nend\s*)$/u;
    if (!postInstallEnd.test(mod.modResults.contents)) {
      throw new Error("Could not find Expo's react_native_post_install block.");
    }

    const override = `
    ${marker}
    deployment_target = podfile_properties['ios.deploymentTarget'] || '16.0'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_configuration|
        build_configuration.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = deployment_target
      end
    end
`;

    mod.modResults.contents = mod.modResults.contents.replace(
      postInstallEnd,
      `$1${override}$2`,
    );
    return mod;
  });
};
